corrected_code:
const express = require('express');
const { Queue } = require('bullmq');
const { Pool } = require('pg');

const app = express();
app.use(express.json());
const pool = new Pool({ connectionString: process.env.DB_URL });

const dlqQueue = new Queue('order-fulfillment-dlq', {
  connection: { host: 'localhost', port: 6379 }
});

app.post('/api/dlq/fulfillment/discard', async (req, res) => {
  if (!req.user || !req.user.storeId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { jobId, discardReason } = req.body;

  const job = await dlqQueue.getJob(jobId);
  if (!job) {
    return res.status(404).json({ error: 'DLQ item not found' });
  }

  // Ensure the failed order job belongs to caller's store
  if (job.data.storeId !== req.user.storeId) {
    return res.status(403).json({ error: 'Forbidden: unauthorized store DLQ access' });
  }

  await job.discard();
  await job.remove();

  await pool.query(
    'INSERT INTO dlq_audit_log (job_id, discarded_by, reason, created_at) VALUES ($1, $2, $3, NOW())',
    [jobId, req.user.storeId, discardReason]
  );

  res.json({ success: true, jobId, discarded: true });
});

app.listen(8010);
